SCHEMA = {
    "название": {"type": str, "required": True},
    "цена":     {"type": (int, float), "required": True, "min": 0},
    "количество": {"type": int, "required": False, "min": 1},
}

def validate(payload):
    errors = []
    for field, rule in SCHEMA.items():
        if field not in payload:
            if rule["required"]:
                errors.append(f"{field}: обязательное поле")
            continue
        value = payload[field]
        if not isinstance(value, rule["type"]) or isinstance(value, bool):
            errors.append(f"{field}: неверный тип")
        elif "min" in rule and value < rule["min"]:
            errors.append(f"{field}: меньше {rule['min']}")
    extra = set(payload) - set(SCHEMA)
    for field in sorted(extra):
        errors.append(f"{field}: лишнее поле, игнорируем")
    return errors

for payload in [
    {"название": "кофе", "цена": 25000, "количество": 2},
    {"цена": -5},
    {"название": "чай", "цена": "дорого", "is_admin": True},
]:
    print(payload)
    problems = validate(payload)
    print("  ", problems or "всё в порядке")

SESSIONS = {"tok-aziz": "azizbek", "tok-dilnoza": "dilnoza"}
ORDERS = {
    101: {"владелец": "azizbek",  "сумма": 250000},
    102: {"владелец": "dilnoza", "сумма": 90000},
}

def get_order(token, order_id):
    # 1. аутентификация: кто ты
    user = SESSIONS.get(token)
    if user is None:
        return 401, "нужен вход"

    order = ORDERS.get(order_id)
    if order is None:
        return 404, "нет такого заказа"

    # 2. авторизация: твоё ли это
    if order["владелец"] != user:
        return 404, "нет такого заказа"

    return 200, order

for token, oid in [("tok-aziz", 101), ("tok-aziz", 102), ("нет", 101), ("tok-aziz", 999)]:
    code, body = get_order(token, oid)
    print(f"токен={token:11} заказ={oid:3} -> {code} {body}")

