queue = []
sent = set()
dead = []

def create_order(order_id):
    queue.append({"type": "email", "order": order_id, "tries": 0})
    return {"status": 201, "order": order_id}   # ответ уходит сразу

attempts = {"count": 0}

def send_email(order_id):
    attempts["count"] += 1
    if attempts["count"] < 3:                    # почта временно недоступна
        raise RuntimeError("SMTP недоступен")
    if order_id in sent:
        return "уже отправлено"                  # идемпотентность
    sent.add(order_id)
    return "письмо отправлено"

def worker(max_tries=5):
    while queue:
        job = queue.pop(0)
        try:
            print(f"заказ {job['order']}:", send_email(job["order"]))
        except RuntimeError as e:
            job["tries"] += 1
            if job["tries"] >= max_tries:
                dead.append(job)
                print(f"заказ {job['order']}: сдаёмся после {job['tries']} попыток")
            else:
                queue.append(job)
                print(f"заказ {job['order']}: {e}, попытка {job['tries']}")

print(create_order(777))
worker()
print("отправлено:", sent, "| в мёртвой очереди:", len(dead))

